import React from 'react';
import { Map, Navigation } from 'lucide-react';

const ZonesTab = () => (
  <div className="w-full h-full bg-[#A1AED1] border-[8px] border-[#47510B] rounded-[50px] p-8 yellow-stack-shadow flex flex-col gap-6">
    <div className="flex justify-between items-center bg-[#47510B] p-6 rounded-3xl border-4 border-[#CAD23C]">
      <h3 className="text-3xl font-[1000] italic text-[#FDFAD8] uppercase tracking-tighter">Sector_Grid_Alpha</h3>
      <Navigation className="text-[#CAD23C] animate-pulse" />
    </div>
    <div className="flex-grow grid grid-cols-2 md:grid-cols-4 gap-4">
      {['North_Zone', 'South_Zone', 'East_Core', 'West_Rim'].map(zone => (
        <button key={zone} className="bg-[#FDFAD8] border-4 border-[#47510B] rounded-2xl p-6 font-black text-[#AB1717] hover:bg-[#CAD23C] transition-all flex flex-col items-center justify-center gap-4">
          <Map size={40} /> {zone}
        </button>
      ))}
    </div>
  </div>
);

export default ZonesTab;
